mapper.select:
SELECT user_id,type,received_at FROM learning_events
WHERE offering_id=#{offeringId}
AND received_at >= #{from,typeHandler=com.learningplatform.common.mybatis.UtcInstantTypeHandler}
AND received_at < #{to,typeHandler=com.learningplatform.common.mybatis.UtcInstantTypeHandler}
ORDER BY received_at,id
